namespace MyApp.Evals.Tests;

/// <summary>
/// Counts whitespace-separated words in the response.
/// Free, deterministic, no LLM needed.
/// </summary>
internal sealed class WordCountEvaluator : IEvaluator
{
    public string Name => "Words";

    public IReadOnlyList<string> EvaluationMetricNames { get; } = new[] { "Words" };

    public Task<EvaluationResult> EvaluateAsync(
        IEnumerable<ChatMessage> messages,
        ChatResponse response,
        IEnumerable<EvaluationContext>? additionalContext = null,
        CancellationToken cancellationToken = default)
    {
        var text = response.Text ?? string.Empty;
        var count = text.Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries).Length;

        var rating = count switch
        {
            < 5 => EvaluationRating.Poor,
            <= 500 => EvaluationRating.Good,
            _ => EvaluationRating.Average
        };

        var result = new EvaluationResult();
        result.Metrics.Add("Words", new EvaluationMetric<long>(count)
        {
            Rating = rating,
            Interpretation = new EvaluationMetricInterpretation
            {
                Rating = rating,
                Failed = count < 1,
                Reason = count < 5 ? "Response too short" : count > 500 ? "Response unusually long" : null
            }
        });

        return Task.FromResult(result);
    }
}

