namespace MyApp.Evals.Tests;

internal static class AgentChatClientFactory
{
    /// <summary>
    /// Resolves the same IChatClient the app uses.
    /// Detected: AddAzureChatCompletionsClient("chat").AddChatClient("chat") at AppHost.cs:2
    ///
    /// The Aspire extension method is only available at runtime under the AppHost.
    /// For standalone test runs, wire a connection string via user-secrets (see below).
    /// </summary>
    public static IChatClient Create()
    {
        var builder = Host.CreateApplicationBuilder();

        // In test hosts (dotnet test), the entry assembly is testhost.exe so
        // user-secrets are NOT auto-loaded by CreateApplicationBuilder.
        builder.Configuration.AddUserSecrets(typeof(AgentChatClientFactory).Assembly, optional: true);

        var connectionString = builder.Configuration.GetConnectionString("chat");
        if (string.IsNullOrEmpty(connectionString))
        {
            throw new InvalidOperationException(
                "EVAL_USE_REAL_AGENT=1 but no connection string found for \"chat\". " +
                "The app uses AddAzureChatCompletionsClient(\"chat\") which Aspire's AppHost " +
                "populates at runtime, but `dotnet test` runs standalone. Wire one of:\n" +
                "  dotnet user-secrets init --project MyApp.Evals.Tests\n" +
                "  # Key-based auth:\n" +
                "  dotnet user-secrets set \"ConnectionStrings:chat\" " +
                "\"Endpoint=https://<host>.services.ai.azure.com/models;Key=<key>;DeploymentId=chat\" --project MyApp.Evals.Tests\n" +
                "  # Entra-ID auth (when key auth is disabled):\n" +
                "  dotnet user-secrets set \"ConnectionStrings:chat\" " +
                "\"Endpoint=https://<host>.services.ai.azure.com/models;DeploymentId=chat\" --project MyApp.Evals.Tests\n" +
                "Note: the hostname strips dashes from the resource name.");
        }

        // Parse connection string and create the chat client
        var parts = connectionString.Split(';')
            .Select(s => s.Split('=', 2))
            .Where(p => p.Length == 2)
            .ToDictionary(p => p[0].Trim(), p => p[1].Trim(), StringComparer.OrdinalIgnoreCase);

        if (!parts.TryGetValue("Endpoint", out var endpoint))
            throw new InvalidOperationException("Connection string \"chat\" is missing the Endpoint segment.");

        parts.TryGetValue("DeploymentId", out var deploymentId);
        parts.TryGetValue("Key", out var key);

        // Use the OpenAI SDK with the Azure AI Inference endpoint
        var options = new Azure.AI.OpenAI.AzureOpenAIClientOptions();
        Azure.AI.OpenAI.AzureOpenAIClient client = key is not null
            ? new(new Uri(endpoint), new System.ClientModel.ApiKeyCredential(key), options)
            : new(new Uri(endpoint), new Azure.Identity.DefaultAzureCredential(), options);

        return client.GetChatClient(deploymentId ?? "chat").AsIChatClient();
    }
}

